const draftId = $('Parse Callback').item.json.draft_id;
const data = $getWorkflowStaticData('global');
const draft = (data.pendingQueue || []).find(d => d.id === draftId);
if (!draft) {
  return { json: { error: "Draft not found in queue", draft_id: draftId } };
}
return { json: {
  systemPrompt: '',
  userMessage: draft.customer_message,
  conversationHistory: draft.conversation_history || 'First contact, no prior messages.',
  historyCount: draft.history_count || 0,
  customerPhone: draft.customer_phone,
  customerName: draft.customer_name || '',
  regenHint: "The previous draft was: \"" + draft.draft_text + "\". The user wants a different angle - try a fresh approach (different tone, yacht, or opening). Stay within all hard rules AND the conversation history above.",
  draft_id: draftId
} };

// Parse the Hermes-bridge regen response, update the existing draft in the queue.
const r = $input.item.json;
let msgs, notes;
if (r && r.ok === true && Array.isArray(r.messages) && r.messages.length > 0) {
  msgs = r.messages.slice(0, 4).map(m => String(m));
  notes = r.notes_for_zayn || '(no notes)';
} else {
  msgs = ['(Hermes bridge returned no draft on regen - check the hermes-bridge service)'];
  notes = '(regen failed: ' + JSON.stringify(r).slice(0, 200) + ')';
}
const draftId = $('Prep Regen').item.json.draft_id;
const data = $getWorkflowStaticData('global');
const entry = (data.pendingQueue || []).find(d => d.id === draftId);
if (entry) {
  entry.messages = msgs;
  entry.draft_text = msgs.join('\n\n');
  entry.notes = notes;
  entry.messages_sent_count = 0;
}
const preview = msgs.length === 1 ? msgs[0] : msgs.map((m, i) => (i + 1) + '. ' + m).join('\n');
return { json: {
  draft_id: draftId,
  new_preview: preview,
  new_notes: notes,
  customer_phone: entry ? entry.customer_phone : 'unknown',
  customer_name: entry ? entry.customer_name : '',
  customer_message: entry ? entry.customer_message : ''
} };

// #4: route an admin Telegram message -> send to a customer, or ack
const msg = $input.item.json.message || {};
const text = (msg.text || '').trim();
const adminChatId = (msg.chat && msg.chat.id) ? msg.chat.id : 5532831477;
const data = $getWorkflowStaticData('global');
const queue = data.pendingQueue || [];

// Step 8: /manual kill switch — return every conversation to approval
if (text.toLowerCase().trim() === '/manual') {
  return { json: { action: 'set_mode', mode_customer_id: '__ALL__', mode_target: 'approval', mode_label: 'ALL conversations', admin_chat_id: adminChatId } };
}

// caps: /caps inspects the autonomous-mode safety caps
if (text.toLowerCase().trim() === '/caps') {
  return { json: { action: 'caps', admin_chat_id: adminChatId } };
}

// (B) /send <chatId> <message>
if (text.toLowerCase().indexOf('/send ') === 0) {
  const rest = text.slice(6).trim();
  const sp = rest.indexOf(' ');
  if (sp < 1) {
    return { json: { action: 'ack', admin_chat_id: adminChatId, ack_text: 'Usage:  /send <chatId> <message>' } };
  }
  return { json: { action: 'send_to_customer', origin: 'slash', target_chatId: rest.slice(0, sp).trim(), final_text: rest.slice(sp + 1).trim(), admin_chat_id: adminChatId } };
}

// (A) reply to a draft message -> send to that draft's customer (any status)
const r = msg.reply_to_message;
if (r && r.message_id) {
  const d = queue.find(x => x.telegram_message_id === r.message_id);
  if (d && text) {
    const _tl = text.toLowerCase().trim();
    const _MODES = { 'let it run': 'autonomous', 'you continue': 'autonomous', 'take back': 'approval', 'pause': 'paused' };
    if (_MODES[_tl]) {
      return { json: { action: 'set_mode', mode_customer_id: d.customer_phone, mode_target: _MODES[_tl], mode_label: (d.customer_name || d.customer_phone), admin_chat_id: adminChatId } };
    }
    if (d.status === 'pending') {
      return { json: { action: 'refine', draft_id: d.id, instruction: text, admin_chat_id: adminChatId } };
    }
    return { json: { action: 'send_to_customer', origin: 'reply', target_chatId: d.customer_phone, final_text: text, draft_id: d.id, admin_chat_id: adminChatId } };
  }
}

// (edit) a draft awaiting an edit
const awaiting = queue.find(x => x.status === 'awaiting_edit');
if (awaiting && text) {
  awaiting.status = 'sent';
  return { json: { action: 'send_to_customer', origin: 'edit', target_chatId: awaiting.customer_phone, final_text: text, draft_id: awaiting.id, admin_chat_id: adminChatId } };
}

return { json: { action: 'ack', admin_chat_id: adminChatId, ack_text: '⚠️ Nothing sent. To message a customer: reply to their draft message, or use  /send <chatId> <message>' } };

// R1: build a failure alert for Zayn from a node error-output item
const j = $input.item.json || {};
const err = j.error || {};
let msg;
try { msg = err.message || err.description || (typeof err === 'string' ? err : '') || JSON.stringify(err); }
catch (e) { msg = 'unrecognised error'; }
let phone = j.customerPhone || j.customer_phone || '';
try { if (!phone && j.draft) phone = j.draft.customer_phone || ''; } catch (e) {}
const text = '\u26a0\ufe0f Phase 1B \u2014 a step failed\n\n'
  + 'The workflow caught the error instead of dying silently.\n\n'
  + 'Error: ' + (msg || 'unknown') + '\n'
  + (phone ? 'Customer: ' + phone + '\n' : '')
  + '\nNothing was force-sent. Open N8N \u2192 Executions to find the failed '
  + 'node and check the pending queue, then handle it manually.';
return { json: { chat_id: 5532831477, alert_text: text } };

